import json, collections
REF="v2026.11.0"
DIGEST="sha256:"+"0"*63+"1"
MCP_LOCAL={"serverCommand":["docker","run","--rm","-i",f"ghcr.io/example-org/mcp-runbooks@{DIGEST}"]}
for name in ["managed-settings.phase1.json","managed-settings.phase2.json"]:
    d=json.load(open(name),object_pairs_hook=collections.OrderedDict)
    perms=d["permissions"]
    deny=perms["deny"]
    add=["Bash(gh pr review *)","Bash(gh api *reviews*)"]
    if name.endswith("phase1.json"):
        add=["Read(~/.config/gh/**)"]+add
    for r in add:
        if r not in deny: deny.append(r)
