        if k=="strictKnownMarketplaces":
            out["extraKnownMarketplaces"]={"example-org-plugins":{"source":{"source":"github","repo":"example-org/claude-plugins","ref":REF},"autoUpdate":False}}
    out["allowedMcpServers"]=[e if "serverUrl" in e else MCP_LOCAL for e in out["allowedMcpServers"]]
    open(name,"w").write(json.dumps(out,indent=2,ensure_ascii=False)+"\n")
print(json.dumps(json.load(open("managed-settings.phase1.json")),indent=1)[:1500])
EOF

